import type { Metadata } from "next";
import { getProfileSafe } from "@/features/portfolio";

// Generated by `pnpm og:image` (scripts/generate-og-image.mjs) into public/.
const OG_IMAGE = {
  url: "/og-image.png",
  width: 1200,
  height: 630,
  type: "image/png",
};

export async function getMetadata(): Promise<Metadata> {
  const profile = await getProfileSafe();
  const name = profile?.name ?? "Sumanth Narem";
  const tagline = profile?.tagline ?? "Writes the code. Runs the cluster.";

  const title = `${name} | Software Developer & DevOps Engineer`;
  const description =
    `${name} is a software developer and DevOps engineer who builds full-stack products with Next.js, ` +
    `Django, and FastAPI, then ships them to Kubernetes on AWS with CI/CD and infrastructure as code. ` +
    `${tagline}`;
  const ogImage = { ...OG_IMAGE, alt: `${name} | Software Developer & DevOps Engineer. ${tagline}` };

  return {
    title: { default: title, template: `%s | ${name}` },
    description,
    applicationName: `${name} Portfolio`,
    authors: [{ name }],
    creator: name,
    keywords: [
      name,
      "Software Developer",
      "DevOps Engineer",
      "Full-Stack Developer",
      "Kubernetes",
      "AWS",
      "Docker",
      "CI/CD",
      "Infrastructure as Code",
      "Next.js",
      "Django",
      "FastAPI",
      "Portfolio",
    ],
    alternates: { canonical: "/" },
    openGraph: {
      title,
      description,
      siteName: `${name} Portfolio`,
      type: "profile",
      locale: "en_US",
      url: "/",
      images: [ogImage],
    },
    twitter: {
      card: "summary_large_image",
      title,
      description,
      images: [ogImage],
    },
    robots: { index: true, follow: true },
    icons: [{ url: "/hi.png", type: "image/png" }],
    metadataBase: new URL(process.env.NEXT_PUBLIC_SITE_URL ?? "http://localhost:3000"),
  };
}
